#ifndef HAVGAMEPATCHER_PATCHDEFINITION_HPP
#define HAVGAMEPATCHER_PATCHDEFINITION_HPP

#include <array>
#include <cstdint>
#include <span>
#include <string_view>

namespace havGamePatcher
{
  using Byte = std::uint8_t;

  struct JoystickPatch
  {
    std::string_view name;
    std::array<Byte, 10> original;
    std::array<Byte, 10> replacement;
  };

  struct PatchSpan
  {
    std::size_t offset;
    std::size_t dataOffset;
    std::size_t size;
  };

  // Convert only the small tables. The generated byte arrays remain unchanged.
  template <class Span, std::size_t Size>
  consteval auto ConvertPatchSpans(const std::array<Span, Size> &source)
  {
    std::array<PatchSpan, Size> result{};

    for (std::size_t index = 0; index < Size; ++index)
    {
      result[index] = {source[index].offset, source[index].dataOffset, source[index].size};
    }

    return result;
  }

  struct FullscreenRecipe
  {
    std::string_view edition;
    std::string_view name;
    std::size_t originalSize;
    std::size_t patchedSize;
    const std::array<Byte, 32> &originalSha256;
    const std::array<Byte, 32> &joystickSha256;
    const std::array<Byte, 32> &patchedSha256;
    std::span<const PatchSpan> spans;
    std::span<const Byte> patchBytes;
    std::span<const Byte> appendBytes;
  };

  enum class SectionMatch
  {
    exact,
    prefix
  };

  struct EmbeddedPatchSection
  {
    std::string_view name;
    SectionMatch match;
  };

  struct GameDefinition
  {
    std::string_view id;
    std::string_view name;
    std::string_view supportedEditions;
    std::span<const JoystickPatch> joystickPatches;
    std::span<const FullscreenRecipe> fullscreenRecipes;
    std::span<const EmbeddedPatchSection> embeddedPatchSections;
    std::string_view fullscreenDescription;
  };
} // namespace havGamePatcher

#endif // HAVGAMEPATCHER_PATCHDEFINITION_HPP
